using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using Object=UnityEngine.Object;
public static class BlendYardRoad {
 const string A="Assets/NewMap/FiveHangars/YardRoadTransition";static Terrain terrain;static TerrainData before;static Vector3[] road;static float[] lengths;const float Start=18,End=100;static float h0,h1,m1;static int serial;
 static float Old(Vector3 p){var q=p-terrain.transform.position;return before.GetInterpolatedHeight(Mathf.Clamp01(q.x/before.size.x),Mathf.Clamp01(q.z/before.size.z))+terrain.transform.position.y;}
 static Vector3 At(float s){int i=Array.FindIndex(lengths,v=>v>=s);i=Mathf.Clamp(i,1,road.Length-1);return Vector3.Lerp(road[i-1],road[i],Mathf.InverseLerp(lengths[i-1],lengths[i],s));}
 static Vector2 Near(Vector3 p){float best=999999,s=0;for(int i=1;i<road.Length;i++){var a=new Vector2(road[i-1].x,road[i-1].z);var d=new Vector2(road[i].x-road[i-1].x,road[i].z-road[i-1].z);var q=new Vector2(p.x,p.z)-a;float t=Mathf.Clamp01(Vector2.Dot(q,d)/d.sqrMagnitude),v=(q-d*t).sqrMagnitude;if(v<best){best=v;s=Mathf.Lerp(lengths[i-1],lengths[i],t);}}return new Vector2(Mathf.Sqrt(best),s);}
 static float Delta(Vector3 p){if(p.x<-18||p.x>62||p.z<23||p.z>115)return 0;return terrain.SampleHeight(p)+terrain.transform.position.y-Old(p);}
 static float Profile(float s){if(s<=Start)return Old(At(s));if(s>=End)return Old(At(s));float t=(s-Start)/(End-Start);return (2*t*t*t-3*t*t+1)*h0+(-2*t*t*t+3*t*t)*h1+(t*t*t-t*t)*(End-Start)*m1;}
 static bool Candidate(MeshFilter f){var r=f.GetComponent<Renderer>();return r&&r.bounds.Intersects(new Bounds(new Vector3(22,40,69),new Vector3(85,300,95)));}
 static int Refit(Transform parent,bool normals){int count=0;foreach(var f in parent.GetComponentsInChildren<MeshFilter>(true)){if(!f.sharedMesh||!Candidate(f)||f.GetComponentInParent<LODGroup>()&&f.name.StartsWith("TFP_"))continue;string path=AssetDatabase.GetAssetPath(f.sharedMesh);if(!path.StartsWith("Assets/NewMap/"))continue;var vertices=f.sharedMesh.vertices;bool changed=false;for(int i=0;i<vertices.Length;i++){var p=f.transform.TransformPoint(vertices[i]);float d=Delta(p);if(Mathf.Abs(d)<.0005f)continue;p.y+=d;vertices[i]=f.transform.InverseTransformPoint(p);changed=true;}if(!changed)continue;var old=f.sharedMesh;var mesh=Object.Instantiate(old);mesh.name=old.name+" - blended yard transition";mesh.vertices=vertices;if(normals)mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,A+"/Refitted detail "+(++serial)+".asset");f.sharedMesh=mesh;foreach(var c in f.GetComponents<MeshCollider>())if(c.sharedMesh==old)c.sharedMesh=mesh;count++;}return count;}
 public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");if(Directory.Exists(A))throw new Exception("Already blended");var root=GameObject.Find("New_Map").transform;terrain=root.GetComponentInChildren<Terrain>();var td=terrain.terrainData;Directory.CreateDirectory(A);AssetDatabase.Refresh();EditorSceneManager.SaveScene(root.gameObject.scene,"Temp/FiveHangars/Gameplay.before-yard-road-blend.unity",true);File.Copy(AssetDatabase.GetAssetPath(td),"Temp/FiveHangars/Terrain.before-yard-road-blend.asset",true);File.Copy("output/NewMap/Revision2/road-centerline.csv","Temp/FiveHangars/road-before-yard-blend.csv",true);before=Object.Instantiate(td);
  road=File.ReadAllLines("output/NewMap/Revision2/road-centerline.csv").Skip(1).Select(l=>{var s=l.Split(',');return new Vector3(float.Parse(s[0],System.Globalization.CultureInfo.InvariantCulture),0,float.Parse(s[2],System.Globalization.CultureInfo.InvariantCulture));}).ToArray();lengths=new float[road.Length];for(int i=1;i<road.Length;i++)lengths[i]=lengths[i-1]+Vector3.Distance(road[i],road[i-1]);h0=Old(At(Start));h1=Old(At(End));m1=Mathf.Clamp((Old(At(End+3))-Old(At(End-3)))/6,0,.14f);
  int n=td.heightmapResolution;var heights=td.GetHeights(0,0,n,n);float maxDelta=0;
  for(int z=0;z<n;z++)for(int x=0;x<n;x++){var p=terrain.transform.position+new Vector3(x/(float)(n-1)*td.size.x,0,z/(float)(n-1)*td.size.z);if(p.x<-18||p.x>62||p.z<23||p.z>115)continue;var near=Near(p);if(near.x>=11||near.y<Start-5||near.y>End+8)continue;float cross=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(4.7f,11,near.x));float fade=Mathf.SmoothStep(0,1,Mathf.InverseLerp(Start-5,Start,near.y))*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(End,End+8,near.y)));float crown=.05f*Mathf.Sin(Mathf.PI*Mathf.Clamp01((near.y-Start)/(End-Start)))*Mathf.Exp(-near.x*near.x/10);float old=heights[z,x]*td.size.y+terrain.transform.position.y;float target=Mathf.Lerp(old,Profile(near.y)+crown,cross*fade);maxDelta=Mathf.Max(maxDelta,Mathf.Abs(target-old));heights[z,x]=(target-terrain.transform.position.y)/td.size.y;}
  td.SetHeights(0,0,heights);terrain.Flush();int refitted=0,regrounded=0;
  AssetDatabase.StartAssetEditing();try{refitted+=Refit(root.Find("09_Original_Road_Details"),true);refitted+=Refit(root.Find("13_Roadside_Farmyards"),true);refitted+=Refit(root.Find("05_Landscape"),false);refitted+=Refit(root.Find("10_Power_Line"),true);}finally{AssetDatabase.StopAssetEditing();}
  foreach(var l in root.Find("05_Landscape").GetComponentsInChildren<LODGroup>(true).Where(l=>l.name.StartsWith("TFP_")&&!l.transform.parent.GetComponentInParent<LODGroup>())){float d=Delta(l.transform.position);if(Mathf.Abs(d)>.0005f){l.transform.position+=Vector3.up*d;regrounded++;}}
  foreach(var parent in new[]{root.Find("09_Original_Road_Details/Rocky road shoulders"),root.Find("10_Power_Line"),root.Find("06_Road_Route")})if(parent)foreach(Transform t in parent){if(parent.name=="10_Power_Line"&&!t.name.StartsWith("TFP_"))continue;float d=Delta(t.position);if(Mathf.Abs(d)>.0005f){t.position+=Vector3.up*d;regrounded++;}}
  // Paint a gradual, rounded narrowing from the broad farmyard to the road.
  n=td.alphamapWidth;var alpha=td.GetAlphamaps(0,0,n,n);for(int z=0;z<n;z++)for(int x=0;x<n;x++){var p=terrain.transform.position+new Vector3(x/(float)(n-1)*td.size.x,0,z/(float)(n-1)*td.size.z);if(p.x<-16||p.x>12||p.z<36||p.z>64)continue;var near=Near(p);float weight=(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(8,12,near.x)))*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(38,48,near.y)));if(weight<=0)continue;float width=Mathf.Lerp(9,4.3f,Mathf.SmoothStep(0,1,Mathf.InverseLerp(20,45,near.y)));float dirt=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(width,width+2,near.x));float variation=Mathf.PerlinNoise(p.x*.06f+100,p.z*.06f+500),grass=1-dirt;float[] v={grass*(.55f+.3f*variation),dirt*.3f,dirt*.08f,0,grass*(.45f-.3f*variation),dirt*.02f,dirt*.6f};for(int l=0;l<td.alphamapLayers;l++)alpha[z,x,l]=Mathf.Lerp(alpha[z,x,l],v[l],weight);}td.SetAlphamaps(0,0,alpha);
  foreach(var p in road.Select((p,i)=>new{p,i}).ToArray())road[p.i].y=terrain.SampleHeight(p.p)+terrain.transform.position.y;var culture=System.Globalization.CultureInfo.InvariantCulture;File.WriteAllLines("output/NewMap/Revision2/road-centerline.csv",new[]{"x,y,z"}.Concat(road.Select(p=>p.x.ToString("F3",culture)+","+p.y.ToString("F3",culture)+","+p.z.ToString("F3",culture))));
  float maxGrade=0,gradeDistance=0;for(float s=Start+.5f;s<End;s+=.5f){var a=At(s-.5f);var b=At(s);float rise=Mathf.Abs(terrain.SampleHeight(b)-terrain.SampleHeight(a));float run=Vector2.Distance(new Vector2(a.x,a.z),new Vector2(b.x,b.z));maxGrade=Mathf.Max(maxGrade,rise/run);gradeDistance+=run;}
  EditorUtility.SetDirty(td);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.gameObject.scene);Object.DestroyImmediate(before);Directory.CreateDirectory("output/NewMap/ShopCorrections");string report="Yard/road transition rebuilt over route distance 18-100m using a smooth cubic ramp with a flat road cross-section and feathered 11m shoulders. Centerline grade max "+(maxGrade*100).ToString("F2")+"%; maximum localized terrain change "+maxDelta.ToString("F2")+"m. "+refitted+" generated detail meshes refitted; "+regrounded+" roadside props/markers regrounded. Broad yard narrows gradually into road; route CSV heights updated. Other route sections and building sites preserved.";File.WriteAllText("output/NewMap/ShopCorrections/road-transition.txt",report);return report;
 }
}
